uid:=(d->>'userId')::uuid;IF NOT EXISTS(SELECT 1 FROM app.app_users WHERE id=uid AND role='guru' AND status='active') THEN RAISE EXCEPTION 'SUBSTITUTE_INVALID' USING ERRCODE='22023';END IF;
