CREATE FUNCTION app.exam_read(p_session text,p_date date,p_period uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE actor uuid;operator boolean;BEGIN actor:=app.activity_guard(p_session,false);operator:=app.actor_is_admin() OR app.is_committee(actor,p_date,p_period);
